string search(int id) -> string {
  struct Person {
    int id;
    string name;
    int salary;
  } person(int id);

  vector<Person> people;
  string result;

  for (int i = 0; i < id; i++) {
    if (person(i).name != null) {
      people.push_back({
        {i, person(i).name, person(i).salary}
      });
    }
  }

  return people;
}

  

